// The wasm host's entry: the page calls `nuclo_start` once the module is instantiated.
// `app.rs` is generated by nuclo-native-ts; `nuclo` is the runtime's backend-independent core,
// and `web_backend` shows it in the DOM (host.ts holds the other half). `native` is the app's own
// platform code, empty when it has none.

mod app;
mod native;
mod nuclo;
mod web_backend;

#[no_mangle]
pub extern "C" fn nuclo_start() {
    web_backend::start(app::nuclo_main);
}
